CREATE TABLE IF NOT EXISTS `routing_governance_states` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `subject_type` TEXT NOT NULL, `subject_id` INT NOT NULL, `model_name` VARCHAR(191) NOT NULL DEFAULT '', `state` VARCHAR(191) NOT NULL DEFAULT 'suppressed', `reason_code` TEXT NOT NULL, `reason_detail` TEXT, `probe_model_name` TEXT, `last_http_status` INT, `failure_count` INT NOT NULL DEFAULT 0, `success_count` INT NOT NULL DEFAULT 0, `suppress_until` VARCHAR(191), `probe_after` TEXT, `last_failure_at` VARCHAR(191), `last_success_at` VARCHAR(191), `last_probe_at` VARCHAR(191), `last_probe_status` TEXT, `last_probe_message` TEXT, `created_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE UNIQUE INDEX `routing_governance_states_subject_scope_unique` ON `routing_governance_states` (`subject_type`(191), `subject_id`, `model_name`(191));
CREATE INDEX `routing_governance_states_reason_state_idx` ON `routing_governance_states` (`reason_code`(191), `state`(191));
CREATE INDEX `routing_governance_states_state_suppress_idx` ON `routing_governance_states` (`state`(191), `suppress_until`, `probe_after`(191));
CREATE INDEX `routing_governance_states_subject_idx` ON `routing_governance_states` (`subject_type`(191), `subject_id`);
